  "sql": "SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, md.molecule_type AS compound_key, COALESCE(d.doi, d.pubmed_id) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN compound_structures cs ON md.molregno = cs.molregno JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid LEFT JOIN docs d ON a.doc_id = d.doc_id WHERE td.chembl_id = 'CHEMBL6020' AND act.standard_type = 'IC50' ORDER BY md.chembl_id, cs.canonical_smiles, md.molecule_type, COALESCE(d.doi, d.pubmed_id), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism"
